// LoadPlayer loads the roundPlayer's Player into the .R struct
func (o *RoundPlayer) LoadPlayer(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.Player = nil
	o.R.Loaded.Player = false

	related, err := o.Player(mods...).One(ctx, exec)
	if err != nil {
		return err
	}

	related.R.RoundPlayers = RoundPlayerSlice{o}

	o.R.Player = related
	o.R.Loaded.Player = true
	return nil
}

// LoadPlayer loads the roundPlayer's Player into the .R struct
func (os RoundPlayerSlice) LoadPlayer(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	players, err := os.Player(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.Player = nil
		o.R.Loaded.Player = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	roundPlayerByKey := make(map[int64][]*RoundPlayer, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		roundPlayerByKey[o.PlayerID] = append(roundPlayerByKey[o.PlayerID], o)
	}

	for _, rel := range players {

		owners, ok := roundPlayerByKey[rel.ID]
		if !ok {
			continue
		}

		for _, o := range owners {

			// to-one: keep only the first matching child (matches the previous break)
			if o.R.Player != nil {
				continue
			}

			rel.R.RoundPlayers = append(rel.R.RoundPlayers, o)

			o.R.Player = rel

		}
	}

	return nil
}

