type roundPlayerJoins[Q dialect.Joinable] struct {
	typ       string
	Player    modAs[Q, playerColumns]
	Round     modAs[Q, roundColumns]
	RoundTeam modAs[Q, roundTeamColumns]
}

func (j roundPlayerJoins[Q]) aliasedAs(alias string) roundPlayerJoins[Q] {
	return buildRoundPlayerJoins[Q](buildRoundPlayerColumns(alias), j.typ)
}

func buildRoundPlayerJoins[Q dialect.Joinable](cols roundPlayerColumns, typ string) roundPlayerJoins[Q] {
	return roundPlayerJoins[Q]{
		typ: typ,
		Player: modAs[Q, playerColumns]{
			c: Players.Columns,
			f: func(to playerColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Players.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.PlayerID),
					))
				}

				return mods
			},
		},
		Round: modAs[Q, roundColumns]{
			c: Rounds.Columns,
			f: func(to roundColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Rounds.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.RoundID),
					))
				}

				return mods
			},
		},
		RoundTeam: modAs[Q, roundTeamColumns]{
			c: RoundTeams.Columns,
			f: func(to roundTeamColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, RoundTeams.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.RoundTeamID),
					))
				}

				return mods
			},
		},
	}
}
